example_queries:
# Research-output cards straight from the DOI registry
PREFIX dcite: <https://w3id.org/rete/datacite#>
SELECT ?doi ?title ?year ?publisher ?type WHERE {
  ?doi dcite:title ?title ;
       dcite:publicationYear ?year ;
       dcite:publisherName ?publisher ;
       dcite:resourceType ?type .
}
LIMIT 25

# Records whose DOI exists only in the 2023 snapshot
PREFIX dcite: <https://w3id.org/rete/datacite#>
SELECT ?doi ?title WHERE {
  ?doi dcite:fromSnapshot dcite:snapshot-2023 ;
       dcite:title ?title .
}
LIMIT 25

# The PID Graph: what a work points at, and why
PREFIX dcite: <https://w3id.org/rete/datacite#>
SELECT ?from ?type ?to ?assertedBy WHERE {
  ?rel a dcite:PidRelation ;
       dcite:relationSubject ?from ;
       dcite:relationType ?type ;
       dcite:relationObject ?to .
  OPTIONAL { ?rel dcite:assertedBy ?assertedBy }
}
LIMIT 25

# Funders of one record as the record names them, joined to Crossref Funder IDs / ROR by IRI
PREFIX dcite: <https://w3id.org/rete/datacite#>
SELECT ?funder ?name WHERE {
  <https://doi.org/10.17638/00008533> dcite:hasFundingReference ?ref .
  ?ref dcite:funder ?funder .
  OPTIONAL { ?ref dcite:funderName ?name }
}
